#include "UiHarness.hpp"

#include <cstdint>
#include <cstdio>
#include <string>

extern "C" {
    #include <quickjs.h>
}

#include "host/rpc/BackendRpcRegistration.hpp"
#include "host/QuickJsGlobals.hpp"
#include "host/js/SharedModules.hpp"
#include "host/packs/ProcessPacks.hpp"
#include "host/js/PackModules.hpp"

// The embedded UI host (QuickJS bytecode) and the app's shared module table it imports from, generated by
// retroplug-modc (CMake retroplug-app-modules) into build/native/ui-bundle_data.c and app-modules_data.c, and linked
// into the test binary.
extern "C" {
    extern const std::uint8_t  rp_ui_bundle[];
    extern const std::uint32_t rp_ui_bundle_size;
    extern const rp_js_module rp_app_modules[];
    extern const std::uint32_t rp_app_modules_count;
}

namespace rpuigf {

UiHarness::UiHarness(std::uint32_t width, std::uint32_t height) : core_(width, height) {}

UiHarness::~UiHarness() {
    rp::host::settleForFree(core_.engine().host());  // a pack half still pending must not outlive its modules
    // server_/transport_ reference the engine's JS context; reset them before core_ tears the engine
    // down (member destruction is reverse-declaration order, which already does this — explicit for
    // clarity).
    server_.reset();
    transport_.reset();
}

bool UiHarness::boot() {
    if (booted_) return true;
    if (!core_.init()) return false;

    LvglJsEngine& engine = core_.engine();
    JSContext* ctx = engine.getContext();
    if (!ctx) return false;

    // rpcpp server over the QuickJS object codec (marshals request/response as live JS objects against
    // ctx — nothing serialized). The transport's async sink is unused (the client is synchronous).
    transport_ = std::make_unique<rpcpp::QuickJSTransport>(ctx, [](JSContext*, JSValue) {});
    server_    = std::make_unique<BackendRpcServer>(*transport_, rpcpp::QuickJSCodec{ctx});
    // The UI reads getFrame + drives pressButton over RPC and its stores use the fs surface; it never
    // touches the audio-render harness, the debugger, or the background driver.
    registerHostRpc(*server_, host_);
    registerEmulatorRpc(*server_, engineSvc_);
    server_->addDiscoveryMethod();

    // globalThis[Symbol.for("plugin")] = { __rpcSend } — the namespace realBackend.ts targets.
    BackendRpcServer* srv = server_.get();
    installPluginNamespace(ctx, [&](JSValue ns) {
        engine.host().bindRpcSend(ns, [srv](JSContext* sctx, JSValueConst req) -> JSValue {
            auto out = srv->processMessage(req);
            if (!out) return JS_NULL;        // notification / no reply
            return out->materialize(sctx);   // owned; handed back to JS synchronously
        });
    });

    rp::host::packs::ensureLaunchPacks();  // before the shared modules: a pack's TS halves are read from what it loaded

    // Eval the UI bundle (the React app + realBackend), then bind the display + mount React.
    // The app's shared modules first: the UI's imports resolve to them by name.
    if (const std::string why = rp::host::registerSharedModules(ctx, rp_app_modules, rp_app_modules_count);
        !why.empty()) {
        std::fprintf(stderr, "[ui-test] %s\n", why.c_str());
        return false;
    }
    rp::host::installPackLoader(ctx, rp::host::packs::processPacks(), rp_app_modules, rp_app_modules_count);
    if (engine.evalModuleBytecode(rp_ui_bundle, rp_ui_bundle_size) != 0) return false;
    engine.attachDisplay();

    booted_ = true;
    return true;
}

} // namespace rpuigf
